export const locationsByPractice = {
  'octavia-aesthetic': AESTHETIC_LOCATIONS,
  'octavia-house':     OCTAVIA_HOUSE_LOCATIONS,
  'new-octavia':       NEW_OCTAVIA_LOCATIONS,
}

export function getLocationBySlug(slug, practiceSlug = 'octavia-aesthetic') {
  const list = locationsByPractice[practiceSlug] ?? AESTHETIC_LOCATIONS
  return list.find(l => l.slug === slug) ?? null
}

